    17→	"github.com/nogo/herald/internal/deployer"
    18→	"github.com/nogo/herald/internal/preview"
    19→	"github.com/nogo/herald/internal/secrets"
    20→	"github.com/nogo/herald/internal/stacks"
    21→	"github.com/nogo/herald/internal/webhook"
    22→	"github.com/spf13/cobra"
    23→)
    24→
    25→var port int
    26→
    27→var serveCmd = &cobra.Command{
    28→	Use:   "serve",
    29→	Short: "Start webhook listener and deploy daemon",
    30→	RunE: func(cmd *cobra.Command, args []string) error {
    31→		store := secrets.NewStore(dataDir)
    32→		secret, err := store.Get("herald/webhook_secret")
    33→		if err != nil {
    34→			return fmt.Errorf("webhook secret not configured. Run: herald secret set herald/webhook_secret <your-secret>")
    35→		}
    36→
    37→		d := &deployer.Deployer{
    38→			Config:  Cfg,
    39→			Secrets: store,
    40→			Logger:  slog.Default(),
    41→		}
    42→
    43→		stackMgr := &stacks.StackManager{
    44→			Config:  Cfg,
    45→			Secrets: store,
    46→			DataDir: dataDir,
    47→			Logger:  slog.Default(),
    48→		}
    49→
    50→		previewMgr := &preview.PreviewManager{
    51→			Config:  Cfg,
    52→			Secrets: store,
    53→			DataDir: dataDir,
    54→			Logger:  slog.Default(),
    55→		}
    56→
    57→		srv := &webhook.Server{
    58→			Config:  Cfg,
    59→			Secret:  secret,
    60→			Verbose: verbose,
    61→			OnDeploy: func(req webhook.DeployRequest) {
    62→				d.DeployAsync(req.AppName)
    63→			},
    64→			IaCRepo:   getIaCRepo(dataDir),
    65→			OnIaCPush: makeIaCPushHandler(stackMgr),
    66→			OnPreviewDeploy: func(appName, branch, commit string) {
    67→				ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
    68→				defer cancel()
    69→				if err := previewMgr.Deploy(ctx, appName, branch, commit); err != nil {
    70→					slog.Error("preview deploy failed", "app", appName, "branch", branch, "error", err)
    71→				}
    72→			},
    73→			OnPreviewTeardown: func(appName, branch string) {
    74→				ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
    75→				defer cancel()
    76→				if err := previewMgr.Teardown(ctx, appName, branch); err != nil {
    77→					slog.Error("preview teardown failed", "app", appName, "branch", branch, "error", err)
    78→				}
    79→			},
    80→		}
    81→
    82→		addr := fmt.Sprintf(":%d", port)
    83→		httpSrv := &http.Server{
    84→			Addr:    addr,
    85→			Handler: srv.Handler(),
    86→		}
    87→
    88→		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
    89→		defer stop()
    90→
    91→		go func() {
    92→			slog.Info("herald server started", "addr", addr)
    93→			if err := httpSrv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
    94→				slog.Error("server error", "error", err)
    95→				stop()
    96→			}
    97→		}()
    98→
    99→		<-ctx.Done()
   100→		stop()
   101→
   102→		if cause := context.Cause(ctx); cause != nil {
   103→			slog.Info("herald server stopping", "cause", cause)
   104→		}
   105→
   106→		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
   107→		defer cancel()
   108→
   109→		if err := httpSrv.Shutdown(shutdownCtx); err != nil {
   110→			return fmt.Errorf("server shutdown: %w", err)
   111→		}
   112→
   113→		d.Wait()
   114→		slog.Info("herald server stopped")
   115→		return nil
   116→	},
   117→}
