   119→// getIaCRepo reads the git remote URL from the IaC repo clone and returns the
   120→// GitHub full name (e.g. "nogo/srv2"), or "" if unavailable.
   121→func getIaCRepo(dataDir string) string {
   122→	repoDir := filepath.Join(dataDir, "repo")
   123→	out, err := exec.Command("git", "-C", repoDir, "remote", "get-url", "origin").Output()
   124→	if err != nil {
   125→		return ""
   126→	}
   127→	return parseGitHubRepo(strings.TrimSpace(string(out)))
   128→}
   129→
   130→// parseGitHubRepo extracts "owner/repo" from a GitHub clone URL.
   131→func parseGitHubRepo(rawURL string) string {
   132→	rawURL = strings.TrimSuffix(rawURL, ".git")
   133→	if after, ok := strings.CutPrefix(rawURL, "https://github.com/"); ok {
   134→		return after
   135→	}
   136→	// git@github.com:owner/repo
   137→	if idx := strings.Index(rawURL, "@github.com:"); idx >= 0 {
   138→		return rawURL[idx+len("@github.com:"):]
   139→	}
   140→	return ""
   141→}
   142→
   143→// makeIaCPushHandler returns a function that triggers auto-deploy for stacks
   144→// with auto_deploy: true, and logs the rest.
   145→func makeIaCPushHandler(mgr *stacks.StackManager) func() {
   146→	return func() {
   147→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Minute)
   148→		defer cancel()
   149→
   150→		for _, info := range mgr.List() {
   151→			if info.AutoDeploy {
   152→				slog.Info("IaC push: auto-deploying stack", "stack", info.Name)
   153→				if err := mgr.ComposeUp(ctx, info.Name); err != nil {
   154→					slog.Error("IaC push: auto-deploy failed", "stack", info.Name, "error", err)
   155→				} else {
   156→					slog.Info("IaC push: auto-deploy complete", "stack", info.Name)
   157→				}
   158→			} else {
   159→				slog.Info("IaC push: stack updated in repo (no auto-deploy)", "stack", info.Name)
   160→			}
   161→		}
   162→	}
   163→}
   164→
   165→func init() {
   166→	rootCmd.AddCommand(serveCmd)
   167→	serveCmd.Flags().IntVar(&port, "port", 8080, "Port to listen on")
   168→}
