    24→// Deployer executes app deploys.
    25→type Deployer struct {
    26→	Config  *config.Config
    27→	Secrets *secrets.Store
    28→	Logger  *slog.Logger
    29→
    30→	appLocks sync.Map      // string → *appLock
    31→	wg       sync.WaitGroup
    32→}
    33→
    34→type appLock struct {
    35→	mu    sync.Mutex
    36→	count atomic.Int32 // goroutines running or waiting, max 2
    37→}
    38→
    39→func (d *Deployer) getAppLock(appName string) *appLock {
    40→	v, _ := d.appLocks.LoadOrStore(appName, &appLock{})
    41→	return v.(*appLock)
    42→}
    43→
    44→// DeployAsync dispatches a deploy in a goroutine with per-app serialization.
    45→// At most one deploy may be queued per app; additional calls are dropped.
    46→func (d *Deployer) DeployAsync(appName string) {
    47→	lock := d.getAppLock(appName)
    48→	if lock.count.Add(1) > 2 {
    49→		lock.count.Add(-1)
    50→		d.Logger.Info("deploy already queued, dropping", "app", appName)
    51→		return
    52→	}
    53→
    54→	d.wg.Go(func() {
    55→		lock.mu.Lock()
    56→		defer lock.mu.Unlock()
    57→		defer lock.count.Add(-1)
    58→
    59→		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
    60→		defer cancel()
    61→
    62→		if err := d.Deploy(ctx, appName); err != nil {
    63→			d.Logger.Error("deploy failed", "app", appName, "error", err)
    64→		}
    65→	})
    66→}
    67→
    68→// Wait blocks until all in-progress deploys finish.
    69→func (d *Deployer) Wait() {
    70→	d.wg.Wait()
    71→}
    72→
    73→// Deploy executes a full deploy for the named app.
    74→func (d *Deployer) Deploy(ctx context.Context, appName string) error {
    75→	app, ok := d.Config.Apps[appName]
    76→	if !ok {
    77→		return fmt.Errorf("app %q not found in config", appName)
    78→	}
    79→
    80→	appDir := filepath.Join(d.Config.Server.StacksDir, "apps", appName)
    81→	start := time.Now()
    82→	d.Logger.Info("deploy started", "app", appName, "dir", appDir)
    83→
    84→	if err := os.MkdirAll(appDir, 0755); err != nil {
    85→		return fmt.Errorf("creating app dir: %w", err)
    86→	}
    87→
    88→	// 1. Git clone or pull.
    89→	if err := d.gitSync(ctx, appDir, app); err != nil {
    90→		return fmt.Errorf("git: %w", err)
    91→	}
    92→
    93→	// 2. Verify env_file exists if configured.
    94→	if app.EnvFile != "" {
    95→		if _, err := os.Stat(app.EnvFile); err != nil {
    96→			return fmt.Errorf("env_file %q not found", app.EnvFile)
    97→		}
    98→	}
    99→
   100→	// 3. Resolve secrets.
   101→	envVars, dockerSecrets, err := d.Secrets.Resolve(app.Secrets)
   102→	if err != nil {
   103→		return fmt.Errorf("resolving secrets: %w", err)
   104→	}
   105→	if len(envVars)+len(dockerSecrets) > 0 {
   106→		d.Logger.Info("secrets resolved",
   107→			"app", appName,
   108→			"env_keys", slices.Sorted(maps.Keys(envVars)),
   109→			"docker_secret_keys", slices.Sorted(maps.Keys(dockerSecrets)),
   110→		)
   111→	}
   112→
   113→	// Open root for scoped file writes.
   114→	appRoot, err := os.OpenRoot(appDir)
   115→	if err != nil {
   116→		return fmt.Errorf("opening app root: %w", err)
   117→	}
   118→	defer appRoot.Close()
   119→
   120→	// 4. Write .env file.
   121→	if err := writeEnvFile(appRoot, envVars); err != nil {
   122→		return fmt.Errorf("writing .env: %w", err)
   123→	}
   124→
   125→	// 5. Write docker secrets.
   126→	if len(dockerSecrets) > 0 {
   127→		secretsDir := filepath.Join(appDir, "secrets")
   128→		if err := os.MkdirAll(secretsDir, 0700); err != nil {
   129→			return fmt.Errorf("creating secrets dir: %w", err)
   130→		}
   131→		secretsRoot, err := appRoot.OpenRoot("secrets")
   132→		if err != nil {
   133→			return fmt.Errorf("opening secrets root: %w", err)
   134→		}
   135→		defer secretsRoot.Close()
   136→		for name, val := range dockerSecrets {
   137→			if err := writeSecret(secretsRoot, name, val); err != nil {
   138→				return fmt.Errorf("writing docker secret %q: %w", name, err)
   139→			}
   140→		}
   141→	}
   142→
   143→	// 6. Generate compose override.
   144→	repoDir := filepath.Join(appDir, "repo")
   145→	composeFile := app.Compose
   146→	if err := d.generateOverride(appRoot, appDir, appName, app, repoDir, composeFile, dockerSecrets); err != nil {
   147→		return fmt.Errorf("generating compose override: %w", err)
   148→	}
   149→
   150→	// 7. Ensure the caddy network exists before compose up.
   151→	if err := ensureCaddyNetwork(ctx, d.Logger); err != nil {
   152→		return fmt.Errorf("ensuring caddy network: %w", err)
   153→	}
   154→
   155→	// 8. Run docker compose up.
   156→	if err := d.runCompose(ctx, appDir, appName, composeFile); err != nil {
   157→		return fmt.Errorf("compose: %w", err)
   158→	}
   159→
   160→	d.Logger.Info("deploy complete", "app", appName, "duration", time.Since(start).Round(time.Millisecond))
   161→	return nil
   162→}
