   164→// gitSync clones the repo on first deploy or fetch+reset on subsequent ones.
   165→func (d *Deployer) gitSync(ctx context.Context, appDir string, app config.App) error {
   166→	repoDir := filepath.Join(appDir, "repo")
   167→	cloneURL := buildCloneURL(d.Config.Server.GithubToken, app.Repo)
   168→
   169→	_, err := os.Stat(repoDir)
   170→	if os.IsNotExist(err) {
   171→		d.Logger.Info("git clone", "repo", app.Repo, "branch", app.Branch)
   172→		return runCmd(ctx, d.Logger, "", "git",
   173→			"clone", "--branch", app.Branch,
   174→			"--single-branch", "--depth", "1",
   175→			cloneURL, repoDir,
   176→		)
   177→	}
   178→	if err != nil {
   179→		return fmt.Errorf("stat repo dir: %w", err)
   180→	}
   181→
   182→	d.Logger.Info("git fetch+reset", "repo", app.Repo, "branch", app.Branch)
   183→	if err := runCmd(ctx, d.Logger, repoDir, "git", "fetch", "origin", app.Branch); err != nil {
   184→		return err
   185→	}
   186→	return runCmd(ctx, d.Logger, repoDir, "git", "reset", "--hard", "origin/"+app.Branch)
   187→}
   188→
   189→// buildCloneURL returns the HTTPS clone URL, embedding the token if provided.
   190→func buildCloneURL(token, repo string) string {
   191→	if token != "" {
   192→		return fmt.Sprintf("https://%s@github.com/%s.git", token, repo)
   193→	}
   194→	return fmt.Sprintf("https://github.com/%s.git", repo)
   195→}
   196→
   197→// writeEnvFile writes KEY=value pairs to .env, sorted by key.
   198→func writeEnvFile(root *os.Root, envVars map[string]string) error {
   199→	f, err := root.OpenFile(".env", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   200→	if err != nil {
   201→		return err
   202→	}
   203→	defer f.Close()
   204→	for _, key := range slices.Sorted(maps.Keys(envVars)) {
   205→		if _, err := fmt.Fprintf(f, "%s=%s\n", key, envVars[key]); err != nil {
   206→			return err
   207→		}
   208→	}
   209→	return nil
   210→}
   211→
   212→// writeSecret writes a docker secret value to a file in the secrets root.
   213→func writeSecret(root *os.Root, name, value string) error {
   214→	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   215→	if err != nil {
   216→		return err
   217→	}
   218→	defer f.Close()
   219→	_, err = f.WriteString(value)
   220→	return err
   221→}
   222→
   223→// --- Compose override generation ---
   224→
   225→type composeOverride struct {
   226→	Services map[string]serviceOverride `yaml:"services"`
   227→	Networks map[string]networkDef      `yaml:"networks,omitempty"`
   228→	Secrets  map[string]secretFileDef   `yaml:"secrets,omitempty"`
   229→}
   230→
   231→type serviceOverride struct {
   232→	Labels   map[string]string `yaml:"labels,omitempty"`
   233→	EnvFile  []string          `yaml:"env_file,omitempty"`
   234→	Secrets  []string          `yaml:"secrets,omitempty"`
   235→	Networks []string          `yaml:"networks,omitempty"`
   236→}
   237→
   238→type networkDef struct {
   239→	External bool `yaml:"external"`
   240→}
   241→
   242→type secretFileDef struct {
   243→	File string `yaml:"file"`
   244→}
   245→
   246→type minimalCompose struct {
   247→	Services map[string]minimalService `yaml:"services"`
   248→}
   249→
   250→type minimalService struct {
   251→	Expose []any `yaml:"expose"`
   252→	Ports  []any `yaml:"ports"`
   253→}
   254→
   255→func (d *Deployer) generateOverride(
   256→	root *os.Root,
   257→	appDir, appName string,
   258→	app config.App,
   259→	repoDir, composeFile string,
   260→	dockerSecrets map[string]string,
   261→) error {
   262→	// Detect service name and port from the app's compose file.
   263→	serviceName, port, err := detectServiceInfo(filepath.Join(repoDir, composeFile), appName)
   264→	if err != nil {
   265→		d.Logger.Warn("could not detect service info, using defaults",
   266→			"app", appName, "error", err)
   267→		serviceName = "app"
   268→		port = "3000"
   269→	}
   270→
   271→	svc := serviceOverride{
   272→		Labels: map[string]string{
   273→			"caddy":               app.Domain,
   274→			"caddy.reverse_proxy": fmt.Sprintf("{{upstreams %s}}", port),
   275→		},
   276→		Networks: []string{"caddy"},
   277→	}
   278→
   279→	if app.EnvFile != "" {
   280→		svc.EnvFile = []string{app.EnvFile}
   281→	}
   282→
   283→	secretNames := slices.Sorted(maps.Keys(dockerSecrets))
   284→	if len(secretNames) > 0 {
   285→		svc.Secrets = secretNames
   286→	}
   287→
   288→	override := composeOverride{
   289→		Services: map[string]serviceOverride{serviceName: svc},
   290→		Networks: map[string]networkDef{"caddy": {External: true}},
   291→	}
   292→
   293→	if len(secretNames) > 0 {
   294→		override.Secrets = make(map[string]secretFileDef, len(secretNames))
   295→		for _, name := range secretNames {
   296→			override.Secrets[name] = secretFileDef{
   297→				File: filepath.Join(appDir, "secrets", name),
   298→			}
   299→		}
   300→	}
   301→
   302→	data, err := yaml.Marshal(override)
   303→	if err != nil {
   304→		return fmt.Errorf("marshaling override: %w", err)
   305→	}
   306→
   307→	// If app has inline override YAML, deep-merge it.
   308→	if app.Override != "" {
   309→		var baseMap, overlayMap map[string]any
   310→		if err := yaml.Unmarshal(data, &baseMap); err != nil {
   311→			return fmt.Errorf("re-parsing generated override: %w", err)
   312→		}
   313→		if err := yaml.Unmarshal([]byte(app.Override), &overlayMap); err != nil {
   314→			return fmt.Errorf("parsing app override YAML: %w", err)
   315→		}
   316→		merged := deepMerge(baseMap, overlayMap)
   317→		data, err = yaml.Marshal(merged)
   318→		if err != nil {
   319→			return fmt.Errorf("marshaling merged override: %w", err)
   320→		}
   321→	}
   322→
   323→	f, err := root.OpenFile("compose.override.yml", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
   324→	if err != nil {
   325→		return err
   326→	}
   327→	defer f.Close()
   328→	_, err = f.Write(data)
   329→	return err
   330→}
   331→
   332→// detectServiceInfo parses a compose file to find the main service name and port.
   333→// Prefers a service named "app", then appName, then the first alphabetically.
   334→func detectServiceInfo(composeFilePath, appName string) (serviceName, port string, err error) {
   335→	data, err := os.ReadFile(composeFilePath)
   336→	if err != nil {
   337→		return "", "", err
   338→	}
   339→
   340→	var mc minimalCompose
   341→	if err := yaml.Unmarshal(data, &mc); err != nil {
   342→		return "", "", err
   343→	}
   344→
   345→	if len(mc.Services) == 0 {
   346→		return "app", "3000", nil
   347→	}
   348→
   349→	names := slices.Sorted(maps.Keys(mc.Services))
   350→	serviceName = names[0]
   351→	for _, n := range names {
   352→		if n == "app" || n == appName {
   353→			serviceName = n
   354→			break
   355→		}
   356→	}
   357→
   358→	port = extractFirstPort(mc.Services[serviceName])
   359→	if port == "" {
   360→		port = "3000"
   361→	}
   362→	return serviceName, port, nil
   363→}
   364→
   365→func extractFirstPort(svc minimalService) string {
   366→	for _, v := range svc.Expose {
   367→		if p := portFromAny(v); p != "" {
   368→			return p
   369→		}
   370→	}
   371→	for _, v := range svc.Ports {
   372→		if p := portFromAny(v); p != "" {
   373→			return p
   374→		}
   375→	}
   376→	return ""
   377→}
   378→
   379→func portFromAny(v any) string {
   380→	switch val := v.(type) {
   381→	case string:
   382→		// "3000", "3000:3000", "0.0.0.0:80:3000"
   383→		parts := strings.Split(val, ":")
   384→		p := strings.TrimSpace(parts[len(parts)-1])
   385→		return p
   386→	case int:
   387→		return fmt.Sprintf("%d", val)
   388→	case map[string]any:
   389→		// long form: {target: 3000, published: 3000}
   390→		if t, ok := val["target"]; ok {
   391→			return portFromAny(t)
   392→		}
   393→	}
   394→	return ""
   395→}
   396→
   397→// deepMerge recursively merges overlay into base. Overlay wins on conflict
   398→// unless both values are maps, in which case they are merged recursively.
   399→func deepMerge(base, overlay map[string]any) map[string]any {
   400→	result := make(map[string]any, len(base))
   401→	for k, v := range base {
   402→		result[k] = v
   403→	}
   404→	for k, v := range overlay {
   405→		if bv, ok := result[k]; ok {
   406→			if bMap, ok := bv.(map[string]any); ok {
   407→				if oMap, ok := v.(map[string]any); ok {
   408→					result[k] = deepMerge(bMap, oMap)
   409→					continue
   410→				}
   411→			}
   412→		}
   413→		result[k] = v
   414→	}
   415→	return result
   416→}
   417→
   418→// ensureCaddyNetwork creates the caddy Docker network if it doesn't exist.
   419→func ensureCaddyNetwork(ctx context.Context, logger *slog.Logger) error {
   420→	cmd := exec.CommandContext(ctx, "docker", "network", "inspect", "caddy")
   421→	if err := cmd.Run(); err == nil {
   422→		return nil
   423→	}
   424→	return runCmd(ctx, logger, "", "docker", "network", "create", "caddy")
   425→}
   426→
   427→// runCompose executes docker compose up -d --build --remove-orphans.
   428→func (d *Deployer) runCompose(ctx context.Context, appDir, appName, composeFile string) error {
   429→	repoDir := filepath.Join(appDir, "repo")
   430→	overrideFile := filepath.Join(appDir, "compose.override.yml")
   431→	d.Logger.Info("compose up", "app", appName, "project", "herald-"+appName)
   432→	return runCmd(ctx, d.Logger, repoDir,
   433→		"docker", "compose",
   434→		"--project-name", "herald-"+appName,
   435→		"-f", composeFile,
   436→		"-f", overrideFile,
   437→		"up", "-d", "--build", "--remove-orphans",
   438→	)
   439→}
   440→
   441→// runCmd executes a command, logs stdout/stderr line-by-line, and returns an
   442→// error on non-zero exit.
   443→func runCmd(ctx context.Context, logger *slog.Logger, dir string, name string, args ...string) error {
   444→	cmd := exec.CommandContext(ctx, name, args...)
   445→	if dir != "" {
   446→		cmd.Dir = dir
   447→	}
   448→
   449→	var stdout, stderr bytes.Buffer
   450→	cmd.Stdout = &stdout
   451→	cmd.Stderr = &stderr
   452→
   453→	start := time.Now()
   454→	runErr := cmd.Run()
   455→	dur := time.Since(start).Round(time.Millisecond)
   456→
   457→	logLines := func(output string, level slog.Level) {
   458→		for line := range strings.Lines(output) {
   459→			line = strings.TrimRight(line, "\n\r")
   460→			if line != "" {
   461→				logger.Log(ctx, level, line, "cmd", name)
   462→			}
   463→		}
   464→	}
   465→
   466→	logLines(stdout.String(), slog.LevelInfo)
   467→	if stderr.Len() > 0 {
   468→		logLines(stderr.String(), slog.LevelWarn)
   469→	}
   470→
   471→	if runErr != nil {
   472→		return fmt.Errorf("%s: %w (duration: %s)", name, runErr, dur)
   473→	}
   474→
   475→	logger.Info("command completed", "cmd", name, "duration", dur)
   476→	return nil
   477→}
   478→

