   130→// parseGitHubRepo extracts "owner/repo" from a GitHub clone URL.
   131→func parseGitHubRepo(rawURL string) string {
   132→	rawURL = strings.TrimSuffix(rawURL, ".git")
   133→	if after, ok := strings.CutPrefix(rawURL, "https://github.com/"); ok {
   134→		return after
   135→	}
   136→	// git@github.com:owner/repo
   137→	if idx := strings.Index(rawURL, "@github.com:"); idx >= 0 {
   138→		return rawURL[idx+len("@github.com:"):]
   139→	}
   140→	return ""
